// Test the independent SVNNUE-v1 backend against full board refreshes. Fixture
// networks are generated by nnue_validation_test.py using Python's independent
// SHA-256/packing implementation; these synthetic weights are not trained nets.
#include <array>
#include <cstdint>
#include <deque>
#include <functional>
#include <iostream>
#include <sstream>
#include <stdexcept>
#include <string>
#include <vector>

#include "bitboard.h"
#include "endgame.h"
#include "evaluate.h"
#include "movegen.h"
#include "piece.h"
#include "position.h"
#include "psqt.h"
#include "search.h"
#include "thread.h"
#include "uci.h"
#include "variant.h"
#include "stockless_core/nnue.h"

using namespace Stockfish;
namespace Neural = Stockfish::Stockless::Neural;

namespace {
unsigned cases = 0;
unsigned failures = 0;
std::uint64_t checks = 0;
std::uint64_t transitions = 0;
std::uint64_t incrementalProbes = 0;
std::string fixtureDirectory;

void require(bool condition, const std::string& description) {
    ++checks;
    if (!condition)
        throw std::runtime_error(description);
}

void run(const std::string& name, const std::function<void()>& body) {
    ++cases;
    try {
        body();
        std::cout << "PASS " << name << '\n';
    } catch (const std::exception& error) {
        ++failures;
        std::cout << "FAIL " << name << ": " << error.what() << '\n';
    }
}

struct Fixture {
    Position pos;
    std::deque<StateInfo> states{1};
    const Variant* variant;
    std::string name;

    explicit Fixture(const std::string& game, const std::string& fen = "", bool chess960 = false)
        : variant(nullptr), name(game) {
        auto found = variants.find(game);
        require(found != variants.end(), "unregistered fixture variant " + game);
        variant = found->second;
        UCI::init_variant(variant);
        PSQT::init(variant);
        pos.set(variant, fen.empty() ? variant->startFen : fen, chess960,
                &states.back(), Threads.main());
    }

    Move parse(const std::string& text) const {
        std::string mutableText = text;
        const Move result = UCI::to_move(pos, mutableText);
        require(result != MOVE_NONE, "illegal NNUE fixture move " + text + " in " + pos.fen());
        return result;
    }

    void make(Move move) {
        states.emplace_back();
        pos.do_move(move, states.back());
        ++transitions;
    }

    void undo(Move move) {
        pos.undo_move(move);
        states.pop_back();
    }
};

void activate(const Fixture& f, const std::string& suffix = "a") {
    std::string error;
    const std::string path = fixtureDirectory + '/' + f.name + '-' + suffix + ".svnnue";
    require(Neural::load_network(path, f.variant, error), "load " + path + ": " + error);
    require(Neural::select_backend("StocklessNNUE", f.variant, error), "activate NNUE: " + error);
}

Neural::Probe check_probe(const Position& position, bool refreshAllowed,
                          const std::string& context) {
    const auto p = Neural::probe(position, true);
    require(p.used, context + ": neural backend silently inactive: " + p.reason);
    require(p.compatible && Neural::applicable(position), context + ": model incompatible");
    require(p.accumulator_matches, context + ": incremental/full-refresh accumulator differs");
    require(p.accumulator == p.refreshed_accumulator, context + ": full-refresh vector differs");
    require(p.generation != 0, context + ": invalid model generation");
    require(p.value == Neural::evaluate(position), context + ": inference/probe Value differs");
    require(p.stm_cp == (position.side_to_move() == WHITE ? p.white_cp : -p.white_cp),
            context + ": WHITE/side-to-move score conversion");
    require(int(p.value) == p.stm_cp * int(PawnValueEg) / 100,
            context + ": centipawn/engine-Value scale differs");
    if (!refreshAllowed) {
        require(!p.refreshed, context + ": make/undo fell back to a full refresh");
        ++incrementalProbes;
    }
    return p;
}

void same_prediction(const Neural::Probe& a, const Neural::Probe& b, const std::string& context) {
    require(a.accumulator == b.accumulator, context + ": accumulator differs");
    require(a.numerator == b.numerator && a.white_cp == b.white_cp
            && a.stm_cp == b.stm_cp && a.value == b.value, context + ": prediction differs");
}

void check_rebuilt(Fixture& f, const Neural::Probe& p) {
    // Build an independent Position, so this does not reuse dirty-piece data,
    // the live accumulator, or make/unmake history from the tested Position.
    Position other;
    StateInfo state{};
    other.set(f.variant, f.pos.fen(false, true), f.pos.is_chess960(), &state, Threads.main());
    const auto fresh = check_probe(other, true, "independent FEN rebuild");
    require(fresh.refreshed, "new Position did not initialize its own accumulator");
    same_prediction(p, fresh, "incremental versus independent Position");
}

struct Snapshot {
    std::string fen;
    std::vector<std::pair<std::uint32_t, std::int32_t>> features;
    Neural::Probe prediction;
};

Snapshot snapshot(Fixture& f, bool allowRefresh = false) {
    return {f.pos.fen(false, true), Neural::sparse_features(f.pos),
            check_probe(f.pos, allowRefresh, "snapshot")};
}

void restore_matches(Fixture& f, const Snapshot& before) {
    require(f.pos.fen(false, true) == before.fen, "undo position/FEN differs");
    require(Neural::sparse_features(f.pos) == before.features, "undo sparse features differ");
    same_prediction(check_probe(f.pos, false, "undo"), before.prediction, "undo");
}

void sequence(Fixture& f, const std::vector<std::string>& texts) {
    check_probe(f.pos, true, "sequence root");
    std::vector<Move> moves;
    std::vector<Snapshot> before;
    for (const auto& text : texts) {
        before.push_back(snapshot(f));
        const Move move = f.parse(text);
        moves.push_back(move);
        f.make(move);
        const auto p = check_probe(f.pos, false, "after " + text);
        check_rebuilt(f, p);
    }
    for (std::size_t i = moves.size(); i-- > 0;) {
        f.undo(moves[i]);
        restore_matches(f, before[i]);
    }
}

void native_walk(const std::string& name) {
    Fixture f(name);
    activate(f);
    const auto initial = snapshot(f, true);
    std::vector<Move> roots;
    for (Move move : MoveList<LEGAL>(f.pos))
        roots.push_back(move);
    require(!roots.empty(), "empty starting move set");
    for (Move move : roots) {
        f.make(move);
        check_rebuilt(f, check_probe(f.pos, false, "each starting move"));
        f.undo(move);
        restore_matches(f, initial);
    }

    std::vector<Move> moves;
    std::vector<Snapshot> before;
    std::uint32_t seed = 0x534e4e31u;
    for (unsigned ply = 0; ply < 48; ++ply) {
        Value result;
        if (f.pos.is_game_end(result)) break;
        std::vector<Move> choices;
        for (Move move : MoveList<LEGAL>(f.pos)) choices.push_back(move);
        if (choices.empty()) break;
        seed = seed * 1664525u + 1013904223u;
        const Move chosen = choices[seed % choices.size()];
        before.push_back(snapshot(f));
        moves.push_back(chosen);
        f.make(chosen);
        check_rebuilt(f, check_probe(f.pos, false, "seeded legal game"));
    }
    require(!moves.empty(), "seeded game made no moves");
    for (std::size_t i = moves.size(); i-- > 0;) {
        f.undo(moves[i]);
        restore_matches(f, before[i]);
    }
    restore_matches(f, initial);
}
} // namespace

int main(int argc, char** argv) {
    if (argc != 2) {
        std::cerr << "Usage: nnue_test FIXTURE_DIRECTORY\n"
                  << "Generate fixtures with tests/nnue_validation_test.py first.\n";
        return 2;
    }
    fixtureDirectory = argv[1];
    pieceMap.init();
    variants.init();
    UCI::init(Options);
    Options["Use NNUE"] = std::string("false");
    PSQT::init(variants.find("chess")->second);
    Bitboards::init();
    Position::init();
    Bitbases::init();
    Endgames::init();
    Threads.set(1);
    Search::clear();
    CurrentProtocol = UCI_GENERAL;

    for (const auto* name : {"chess", "shogi", "janggi", "xiangqi", "makruk"})
        run(std::string("incremental/all-root-and-seeded-game/") + name,
            [=]() { native_walk(name); });

    run("incremental/chess-capture-and-en-passant", []() {
        Fixture f("chess");
        activate(f);
        sequence(f, {"e2e4", "g8f6", "e4e5", "d7d5", "e5d6", "c7d6"});
    });
    run("incremental/chess-four-promotion-types", []() {
        Fixture f("chess", "7k/P7/8/8/8/8/8/4K3 w - - 0 1");
        activate(f);
        for (const char* text : {"a7a8q", "a7a8r", "a7a8b", "a7a8n"}) sequence(f, {text});
    });
    run("incremental/chess-castling-both-sides", []() {
        Fixture f("chess", "4k3/8/8/8/8/8/8/R3K2R w KQ - 0 1");
        activate(f);
        sequence(f, {"e1g1"});
        sequence(f, {"e1c1"});
    });
    run("incremental/shogi-pocket-count-and-drop", []() {
        Fixture f("shogi", "4k4/9/9/9/4P4/9/9/9/4K4[PPN] w - - 0 1");
        activate(f);
        require(f.pos.count_in_hand(WHITE, SHOGI_PAWN) == 2, "fixture must use scalar pocket count two");
        sequence(f, {"P@d5"});
        sequence(f, {"N@c5"});
    });
    run("incremental/shogi-mandatory-and-optional-promotion", []() {
        Fixture forced("shogi", "8k/3P5/9/9/9/9/9/9/4K4[] w - - 0 1");
        activate(forced);
        sequence(forced, {"d8d9+"});
        Fixture optional("shogi", "8k/9/9/3P5/9/9/9/9/4K4[] w - - 0 1");
        sequence(optional, {"d6d7+"});
        sequence(optional, {"d6d7"});
    });
    run("incremental/shogi-capture-promote-demote-to-pocket", []() {
        Fixture f("shogi", "lnsgkgsnl/1r5b1/ppppppppp/S8/9/9/PPPPPPPPP/1B5R1/LNSGKG1NL[] w 0 1");
        activate(f);
        sequence(f, {"a6a7+", "a9a7"});
        f.make(f.parse("a6a7+"));
        f.make(f.parse("a9a7"));
        require(f.pos.count_in_hand(BLACK, SILVER) == 1
                && f.pos.count_in_hand(BLACK, GOLD) == 0,
                "capture must put unpromoted silver in black pocket");
        check_rebuilt(f, check_probe(f.pos, false, "captured promoted silver"));
    });
    run("incremental/janggi-pass-keeps-board-changes-head", []() {
        Fixture f("janggi", "4k4/c7R/9/3R1R3/9/9/9/9/9/3K5 b - - 0 1");
        activate(f);
        const auto before = snapshot(f, true);
        const Move move = f.parse("e10e10");
        f.make(move);
        const auto after = check_probe(f.pos, false, "Janggi pass");
        require(after.accumulator == before.prediction.accumulator, "pass changed board accumulator");
        require(Neural::sparse_features(f.pos) == before.features, "pass changed board features");
        check_rebuilt(f, after);
        f.undo(move);
        restore_matches(f, before);
    });
    run("incremental/janggi-screened-capture", []() {
        Fixture f("janggi", "1Pbcka3/3nNn1c1/N2CaC3/1pB6/9/9/5P3/9/4K4/9 w - - 0 23");
        activate(f);
        sequence(f, {"f8f10"});
    });
    run("incremental/janggi-palace-discovery", []() {
        Fixture f("janggi", "4ka3/4a4/9/4R4/2B6/9/9/5K3/4p4/3r5 b - - 0 113");
        activate(f);
        sequence(f, {"e2f2"});
    });
    run("incremental/xiangqi-cannon-capture-rook-recapture", []() {
        Fixture f("xiangqi");
        activate(f);
        sequence(f, {"h3h10", "i10h10"});
    });
    run("incremental/makruk-promotes-to-native-met", []() {
        Fixture f("makruk", "7k/8/8/3P4/8/8/8/4K3 w - - 0 1");
        activate(f);
        sequence(f, {"d5d6m"});
    });
    run("incremental/null-move-and-head-selection", []() {
        Fixture f("chess");
        activate(f);
        const auto before = snapshot(f, true);
        f.states.emplace_back();
        f.pos.do_null_move(f.states.back());
        const auto after = check_probe(f.pos, false, "null move");
        require(before.prediction.accumulator == after.accumulator, "null move changed features");
        require(f.pos.side_to_move() == BLACK, "null move did not change output head");
        check_rebuilt(f, after);
        f.pos.undo_null_move();
        f.states.pop_back();
        restore_matches(f, before);
    });
    run("generation/reload-while-child-then-undo-to-parent", []() {
        Fixture f("chess");
        activate(f);
        const auto oldRoot = snapshot(f, true);
        const Move first = f.parse("e2e4");
        f.make(first);
        const Move second = f.parse("g8f6");
        f.make(second);
        const auto oldChild = check_probe(f.pos, false, "before reload");
        activate(f, "b");
        const auto newChild = check_probe(f.pos, true, "new model at live child");
        require(newChild.refreshed && newChild.generation != oldChild.generation,
                "new network did not invalidate live accumulator");
        require(newChild.accumulator != oldChild.accumulator, "replacement fixture network identical");
        check_rebuilt(f, newChild);
        f.undo(second);
        check_rebuilt(f, check_probe(f.pos, false, "undo through pre-reload StateInfo"));
        f.undo(first);
        const auto newRoot = check_probe(f.pos, false, "new model at old root");
        require(newRoot.accumulator != oldRoot.prediction.accumulator, "undo restored stale old model");
        check_rebuilt(f, newRoot);
        // Loading again and making/undoing before any evaluation must also work:
        // hooks must not apply new weights to an old-generation accumulator.
        activate(f, "a");
        f.make(first);
        f.undo(first);
        const auto refresh = check_probe(f.pos, true, "reload and undo before evaluation");
        require(refresh.refreshed, "invalid generation unexpectedly reused");
        same_prediction(refresh, oldRoot.prediction, "return to original model");
    });
    run("generation/classical-interval-and-reactivation", []() {
        Fixture f("chess");
        activate(f);
        const auto old = check_probe(f.pos, true, "before Classical");
        std::string error;
        require(Neural::select_backend("Classical", f.variant, error), error);
        f.make(f.parse("e2e4"));
        require(!Neural::probe(f.pos).used && !Neural::applicable(f.pos), "Classical used NNUE");
        require(Neural::select_backend("StocklessNNUE", f.variant, error), error);
        const auto p = check_probe(f.pos, true, "after Classical");
        require(p.refreshed && p.generation != old.generation, "backend toggle reused old accumulator");
        check_rebuilt(f, p);
    });
    run("isolation/two-live-positions-interleaved", []() {
        Fixture first("chess");
        Fixture second("chess");
        activate(first);
        const auto untouched = snapshot(second, true);
        check_probe(first.pos, true, "first independent Position");
        first.make(first.parse("e2e4"));
        check_rebuilt(first, check_probe(first.pos, false, "first changed Position"));
        restore_matches(second, untouched);
        const auto saved = snapshot(first);
        second.make(second.parse("d2d4"));
        check_rebuilt(second, check_probe(second.pos, false, "second changed Position"));
        restore_matches(first, saved);
    });
    run("arithmetic/signed-half-ties", []() {
        Fixture f("chess");
        activate(f, "rounding");
        const auto white = check_probe(f.pos, true, "positive half tie");
        require(white.numerator == 8192 && white.white_cp == 1 && white.stm_cp == 1,
                "positive half tie must round away from zero");
        f.states.emplace_back();
        f.pos.do_null_move(f.states.back());
        const auto black = check_probe(f.pos, false, "negative half tie");
        require(black.numerator == -8192 && black.white_cp == -1 && black.stm_cp == 1,
                "negative half tie and black score perspective");
        f.pos.undo_null_move();
        f.states.pop_back();
    });
    run("compatibility/chess960-mode-falls-back", []() {
        Fixture f("chess", "4k3/8/8/8/8/8/8/R1K4R w AH - 0 1", true);
        activate(f);
        const auto p = Neural::probe(f.pos);
        require(!p.used && !Neural::applicable(f.pos), "untrained Chess960 mode silently accepted");
        require(!p.reason.empty(), "Chess960 fallback lacks a reason");
    });
    run("compatibility/same-geometry-different-game", []() {
        Fixture chess("chess");
        activate(chess);
        Fixture makruk("makruk");
        Neural::variant_changed(makruk.variant);
        const auto p = Neural::probe(makruk.pos);
        require(!p.used && !Neural::applicable(makruk.pos), "chess weights accepted for Makruk");
        std::string error;
        require(!Neural::select_backend("StocklessNNUE", makruk.variant, error),
                "explicit incompatible activation must reject");
        require(!error.empty(), "incompatible activation lacks diagnostic");
    });

    Threads.set(0);
    variants.clear_all();
    pieceMap.clear_all();
    std::cout << "NNUE_TEST_RESULT {\"cases\":" << cases << ",\"checks\":" << checks
              << ",\"transitions\":" << transitions
              << ",\"incremental_probes\":" << incrementalProbes
              << ",\"failures\":" << failures << "}\n";
    return failures ? 1 : 0;
}
